import { readFileSync } from "node:fs";
import { resolve } from "node:path";

/** The table is generated by scripts/gen.mjs. Never edit it by hand. */
const TABLE = JSON.parse(readFileSync(resolve(import.meta.dirname, "../generated/squares.json"), "utf8"));

export function squareOf(n) {
  const v = TABLE[String(n)];
  if (v === undefined) throw new Error(`out of range: ${n}`);
  return v;
}
